import sys
lat = Lattices.latticeFromJoin("chain2j", join2)
m3 = Lattices.latticeFromJoin("M3", join_m3)
def _labs(xs):
    if xs is None:
        return None
    return sorted([int(str(x)) for x in list(xs)])
def _lab(x):
    if x is None:
        return None
    try:
        return int(str(x))
    except Exception:
        return str(x)
if sys.platform.startswith("java"):
    a0 = lat.getElement(0)
    a1 = lat.getElement(1)
    try:
        from java.util import ArrayList
        join_args = ArrayList()
        join_args.add(a0)
        join_args.add(a1)
        empty_args = ArrayList()
    except Exception:
        join_args = [a0, a1]
        empty_args = []
else:
    a0 = 0
    a1 = 1
    join_args = [a0, a1]
    empty_args = []

